var i=[{title:`Variablen, die du anpassen kannst`,text:`Hebelwirkung, Widerstand, Stütze, Bewegungsumfang und Tempo verändern alle, wie schwer eine Übung ist. Ein Schräg-Liegestütz ist im Allgemeinen leichter als ein Liegestütz am Boden, weil deine Arme weniger von deinem Körpergewicht tragen. Eine leichte Kurzhantel macht eine Kniebeuge schwerer, und das Festhalten an einer stabilen Stütze erleichtert das Balancieren bei einem Ausfallschritt.`},{title:`Beispiele zum Liegestütz`,text:`Beginne an einer Wand oder einer stabilen hohen Fläche und senke deine Hände dann auf eine sichere Bank oder Arbeitsplatte, wenn du stärker wirst. Gehe zu Liegestützen am Boden über und später, wenn es nützlich ist, zu einer Variante mit erhöhten Füßen oder mit Last. Ein Liegestütz auf den Knien und die verschiedenen Schräg-Liegestütze sind nicht alle gleich schwer, teste also, welcher dich kontrollierte Wiederholungen machen lässt.`},{title:`Beispiele zu Kniebeuge und Ziehen`,text:`Eine Stuhl-Kniebeuge kann zu einer Kniebeuge mit Körpergewicht ohne Stütze und dann zu einer Goblet-Kniebeuge führen. Beim vertikalen Ziehen können ein Latzug oder ein unterstützter Klimmzug vor Wiederholungen ohne Hilfe kommen. Schreibe jede Änderung bei Griff, Unterstützung, Bewegungsumfang oder Last auf, damit du weißt, was eine bessere Zahl in deinem Tagebuch wirklich bedeutet.`},{title:`Wann du wechseln solltest`,text:`Steige auf, wenn du deinen Zielbereich mit stabiler Technik und moderater Anstrengung erreichst. Gehe zurück, wenn sich dein Körper stark verdrehen oder verschieben muss, um durch die Übung zu kommen, wenn du immer wieder Wiederholungen nicht schaffst oder wenn dir die Gleichgewichtsanforderung unsicher vorkommt. Wenn sich etwas unangenehm anfühlt, höre auf und überdenke es. Schmerz, der anhält oder sich ungewöhnlich anfühlt, braucht eine Untersuchung durch eine Ärztin, einen Arzt oder eine Physiotherapeutin bzw. einen Physiotherapeuten.`},{title:`TrainUp nutzen`,text:`Dein Plan wählt Übungen, die zu deinem Level, deiner Koordination, deiner Ausrüstung, deiner Deckenhöhe, deiner Bodenfläche und allen Einschränkungen passen, die du festlegst. Wenn du ihn neu erstellst, ändert er sich jeweils um einen Schritt. Er wird nur dann härter, wenn deine letzten 4 Trainings leicht (RPE 5 oder weniger) und vollständig ohne kürzlichen Schmerz waren, und leichter, wenn 2 der letzten 3 sehr hart (RPE 9 oder mehr) oder zu weniger als 60 % abgeschlossen waren.`}];var t=[{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Mayo Clinic: Technik beim Krafttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};